package com.medicore.order.controller; import com.medicore.order.dto.*; import com.medicore.order.service.OrderService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService service; public OrderController(OrderService service){this.service=service;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public OrderResponse create(@Valid @RequestBody OrderRequest r){return service.create(r);} @GetMapping("/{id}") public OrderResponse find(@PathVariable Long id){return service.find(id);}}
